{"name":"intel_runtime_pm_disable","qualified_name":"workspace-linux.drivers.gpu.drm.i915.intel_runtime_pm.intel_runtime_pm_disable","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/intel_runtime_pm.c","start_line":500,"end_line":513,"source":"void intel_runtime_pm_disable(struct intel_runtime_pm *rpm)
{
	struct drm_i915_private *i915 = rpm_to_i915(rpm);
	struct device *kdev = rpm->kdev;

	/* Transfer rpm ownership back to core */
	drm_WARN(&i915->drm, pm_runtime_get_sync(kdev) < 0,
		 "Failed to pass rpm ownership back to core\n");

	pm_runtime_dont_use_autosuspend(kdev);

	if (!rpm->available)
		pm_runtime_put(kdev);
}
